-- Regression: the envelope of a CircularString read from WKB must cover every point.
--
-- Points are handed to the consumer in batches, and each batch after the first has to
-- carry the previous batch's last point so the arcs stay connected. The carry used to
-- take the wrong slot, dropping one point per full batch: the point below at index 17
-- was lost and the envelope came out as x[0..1.6] instead of reaching x=1000.
--
-- The blob deliberately carries no envelope in its header, so ST_MaxX has to recompute
-- it from the geometry rather than read a stored one.
SELECT 'maxx_ok=' || (ST_MaxX(X'') >= 1000.0) || ' maxy_ok=' || (ST_MaxY(X'') >= 1000.0);
